package com.collectionlogexporter;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

public class HiscorePageCountersTest
{
	@Test
	public void mapsBossGroupedClueAndMinigameCounters()
	{
		Map<HiscoreSkill, Skill> skills = new HashMap<>();
		skills.put(HiscoreSkill.ABYSSAL_SIRE, score(25));
		skills.put(HiscoreSkill.CALLISTO, score(10));
		skills.put(HiscoreSkill.ARTIO, score(20));
		skills.put(HiscoreSkill.CLUE_SCROLL_EASY, score(101));
		skills.put(HiscoreSkill.RIFTS_CLOSED, score(55));

		Map<String, String> counters = HiscorePageCounters.map(
			new HiscoreResult("Player", skills),
			Arrays.asList(
				page("Bosses", "Abyssal Sire"),
				page("Bosses", "Callisto and Artio"),
				page("Clues", "Easy Treasure Trails"),
				page("Minigames", "Guardians of the Rift"),
				page("Other", "Random Events")));

		assertEquals("Jagex hiscores: 25", counters.get("abyssal sire"));
		assertEquals("Jagex hiscores: 30", counters.get("callisto and artio"));
		assertEquals("Jagex hiscores: 101", counters.get("easy treasure trails"));
		assertEquals("Jagex hiscores: 55", counters.get("guardians of the rift"));
		assertFalse(counters.containsKey("random events"));
	}

	@Test
	public void doesNotUnderCountCombinedPageWhenAComponentIsUnranked()
	{
		Map<HiscoreSkill, Skill> skills = new HashMap<>();
		skills.put(HiscoreSkill.CALLISTO, score(10));

		Map<String, String> counters = HiscorePageCounters.map(
			new HiscoreResult("Player", skills),
			Arrays.asList(page("Bosses", "Callisto and Artio")));

		assertFalse(counters.containsKey("callisto and artio"));
	}

	private static PageDefinition page(String category, String name)
	{
		return new PageDefinition(category, name, new int[]{1});
	}

	private static Skill score(int value)
	{
		return new Skill(1, value, -1);
	}
}

package com.collectionlogexporter;

import java.util.Arrays;
import java.util.Collections;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertTrue;

public class ExporterPanelTest
{
	@Test
	public void unlocksAfterSnapshotWhileChecklistTracksOptionalKcCoverage() throws Exception
	{
		ExporterPanel[] holder = new ExporterPanel[1];
		SwingUtilities.invokeAndWait(() -> holder[0] = new ExporterPanel(
			() -> { },
			(path, options) -> { },
			() -> EstimateMode.AUTO));
		ExporterPanel panel = holder[0];
		assertNotSame(panel, panel.getWrappedPanel());
		assertFalse(panel.isExportUnlocked());

		panel.setPageChecklist(Arrays.asList(
			new PageDefinition("Bosses", "First boss", new int[]{1}),
			new PageDefinition("Other", "Counterless page", new int[]{2})),
			Collections.emptySet());
		panel.setReady(0, -1, -1, 2, 2, 0, 2);
		flushEdt();
		assertTrue(panel.isExportUnlocked());

		panel.markPageVisited("First boss");
		panel.setReady(0, -1, -1, 2, 2, 1, 2);
		flushEdt();
		assertTrue(panel.isPageChecked("First boss"));
		assertTrue(panel.isExportUnlocked());
		assertTrue(panel.pageListPosition("Counterless page")
			< panel.pageListPosition("First boss"));

		panel.markPageVisited("Counterless page");
		panel.setReady(0, -1, -1, 2, 2, 2, 2);
		flushEdt();
		assertTrue(panel.isPageChecked("Counterless page"));
		assertTrue(panel.isExportUnlocked());
	}

	@Test
	public void officialProgressDrivesTheGlobalMissingTotal() throws Exception
	{
		ExporterPanel[] holder = new ExporterPanel[1];
		SwingUtilities.invokeAndWait(() -> holder[0] = new ExporterPanel(
			() -> { },
			(path, options) -> { },
			() -> EstimateMode.AUTO));

		holder[0].setReady(914, 910, 1706, 97, 808, 81, 123);
		flushEdt();

		assertTrue(holder[0].countText().contains("796 unique missing slots (official)"));
		assertTrue(holder[0].countText().contains("808 currently identified by item scan"));
	}

	private static void flushEdt() throws Exception
	{
		SwingUtilities.invokeAndWait(() -> { });
	}
}

package com.collectionlogexporter;

import com.google.gson.Gson;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class EstimateCatalogTest
{
	@Test
	public void loadsBundledRatesAndChoosesAccountProfile() throws Exception
	{
		EstimateCatalog catalog = EstimateCatalog.load(new Gson());
		assertTrue(catalog.supportedItemCount() > 1_000);

		ItemEstimate main = catalog.estimate(13262, "Abyssal orphan", false);
		ItemEstimate iron = catalog.estimate(13262, "Abyssal orphan", true);
		assertTrue(main.isKnown());
		assertTrue(iron.isKnown());
		assertEquals("Killing abyssal sire (on task)", main.getActivity());
		assertTrue(iron.getEstimatedHours() > main.getEstimatedHours());
	}

	@Test
	public void fallsBackToItemNameAndLeavesUnknownsBlank() throws Exception
	{
		EstimateCatalog catalog = EstimateCatalog.load(new Gson());
		assertTrue(catalog.estimate(-1, "Abyssal orphan", false).isKnown());
		assertFalse(catalog.estimate(-1, "Definitely not a real item", false).isKnown());
	}

	@Test
	public void incompleteEstimateCoverageDoesNotInventPageEta() throws Exception
	{
		EstimateCatalog catalog = EstimateCatalog.load(new Gson());
		ExportData data = new ExportDataBuilder(catalog).build(
			"Player",
			Collections.singletonList(new PageDefinition("Other", "Test", new int[]{13262, -999})),
			Collections.emptyMap(),
			id -> id == 13262 ? "Abyssal orphan" : "Unknown",
			page -> "",
			(page, id) -> "",
			false,
			SortMode.CLOSEST,
			-1,
			-1);

		assertEquals(1, data.getPages().size());
		assertFalse(Double.isFinite(data.getPages().get(0).getEstimatedHours()));
		assertEquals(2, data.getRows().size());
	}

	@Test
	public void cacheVariationNameFallbackCountsConfirmedOwnership() throws Exception
	{
		EstimateCatalog catalog = EstimateCatalog.load(new Gson());
		ExportData data = new ExportDataBuilder(catalog).build(
			"Player",
			Collections.singletonList(new PageDefinition("Bosses", "Abyssal Sire", new int[]{13262})),
			Collections.singletonMap(-1, 1),
			id -> "Abyssal orphan",
			page -> "",
			(page, id) -> "",
			false,
			SortMode.CLOSEST,
			910,
			1706);

		assertTrue(data.getPages().isEmpty());
		assertTrue(data.getRows().isEmpty());
		assertEquals(1, data.getScannedObtained());
		assertEquals(1, data.getScannedTotal());
		assertEquals(910, data.getOfficialObtained());
		assertEquals(1706, data.getOfficialTotal());
	}

	@Test
	public void sharedSlotsAreEmittedOnlyOnceAcrossPages() throws Exception
	{
		EstimateCatalog catalog = EstimateCatalog.load(new Gson());
		ExportData data = new ExportDataBuilder(catalog).build(
			"Player",
			java.util.Arrays.asList(
				new PageDefinition("Clues", "Hard Treasure Trails", new int[]{13262}),
				new PageDefinition("Clues", "Elite Treasure Trails", new int[]{13262, -999})),
			Collections.emptyMap(),
			id -> id == 13262 ? "Abyssal orphan" : "Unknown",
			page -> "",
			(page, id) -> "",
			false,
			SortMode.LOG_ORDER,
			0,
			2);

		assertEquals(2, data.getPages().size());
		assertEquals(2, data.getRows().size());
		assertEquals(2, data.getScannedTotal());
	}

	@Test
	public void creditsCompletedKcAndMarksItemsOverRateAsAnytime()
	{
		ItemEstimate estimate = new ItemEstimate("Boss", 20.0, 100.0, 5.0, "Standard");
		assertEquals(50.0, estimate.effectiveAttemptsRemaining(50), 0.001);
		assertEquals(2.5, estimate.effectiveHours(50), 0.001);
		assertTrue(estimate.isAnytime(120));
		assertEquals(20.0, estimate.kcOverRate(120), 0.001);
		assertEquals(0.0, estimate.effectiveHours(120), 0.001);
		assertEquals(1457, AttemptCounter.fromText("Boss kills: 1,457"));
	}

	@Test
	public void scrollCasesUseTheirOwnTierCountAndCumulativeMilestone() throws Exception
	{
		EstimateCatalog catalog = EstimateCatalog.load(new Gson());
		int minor = ItemID.SCROLL_CASE_BEGINNER_MINOR;
		int major = ItemID.SCROLL_CASE_BEGINNER_MAJOR;
		Map<Integer, String> names = new HashMap<>();
		names.put(minor, "Minor beginner scroll case");
		names.put(major, "Major beginner scroll case");

		ExportData data = new ExportDataBuilder(catalog).build(
			"Player",
			Collections.singletonList(
				new PageDefinition("Clues", "Scroll Cases", new int[]{minor, major})),
			Collections.emptyMap(),
			names::get,
			page -> "",
			(page, id) -> "Jagex hiscores - Beginner clues completed: 25",
			false,
			SortMode.CLOSEST,
			0,
			2);

		assertEquals(2, data.getRows().size());
		ExportRow minorRow = data.getRows().stream()
			.filter(row -> row.getItemId() == minor)
			.findFirst()
			.orElseThrow(AssertionError::new);
		ExportRow majorRow = data.getRows().stream()
			.filter(row -> row.getItemId() == major)
			.findFirst()
			.orElseThrow(AssertionError::new);

		assertEquals(25, minorRow.getCompletedAttempts());
		assertEquals(25, majorRow.getCompletedAttempts());
		assertEquals(50.0, minorRow.getExpectedAdditionalAttempts(), 0.001);
		assertEquals(100.0, majorRow.getExpectedAdditionalAttempts(), 0.001);
		assertEquals(25.0, minorRow.getAttemptsToRate(), 0.001);
		assertEquals(75.0, majorRow.getAttemptsToRate(), 0.001);
		assertEquals(
			majorRow.getEstimatedItemHours(),
			data.getPages().get(0).getEstimatedHours(),
			0.001);
	}

	@Test
	public void scrollCaseItemsCanUseDifferentTierCounters() throws Exception
	{
		EstimateCatalog catalog = EstimateCatalog.load(new Gson());
		int beginner = ItemID.SCROLL_CASE_BEGINNER_MINOR;
		int medium = ItemID.SCROLL_CASE_MEDIUM_MAJOR;

		ExportData data = new ExportDataBuilder(catalog).build(
			"Player",
			Collections.singletonList(
				new PageDefinition("Clues", "Scroll Cases", new int[]{beginner, medium})),
			Collections.emptyMap(),
			id -> id == beginner
				? "Minor beginner scroll case"
				: "Major medium scroll case",
			page -> "",
			(page, id) -> id == beginner
				? "Beginner clues completed: 60"
				: "Medium clues completed: 120",
			false,
			SortMode.CLOSEST,
			0,
			2);

		ExportRow beginnerRow = data.getRows().stream()
			.filter(row -> row.getItemId() == beginner)
			.findFirst()
			.orElseThrow(AssertionError::new);
		ExportRow mediumRow = data.getRows().stream()
			.filter(row -> row.getItemId() == medium)
			.findFirst()
			.orElseThrow(AssertionError::new);

		assertTrue(beginnerRow.isItemAnytime());
		assertEquals(10.0, beginnerRow.getKcOverRate(), 0.001);
		assertEquals(120, mediumRow.getCompletedAttempts());
		assertEquals(250.0, mediumRow.getExpectedAdditionalAttempts(), 0.001);
		assertEquals(130.0, mediumRow.getAttemptsToRate(), 0.001);
	}
}

package com.collectionlogexporter;

import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

final class XlsxExporter
{
	private static final int FILTER_BUTTON_PIXELS = 18;
	private static final int LOGO_DISPLAY_PIXELS = 144;
	private static final long LOGO_EMU = LOGO_DISPLAY_PIXELS * 9_525L;
	private static final String SUPPORT_LABEL = "Support GSVS UK ACM on Patreon";
	private static final String SUPPORT_URL =
		"https://www.patreon.com/GSVS_UK_ACM/posts/buy-us-virtual-165207029";
	private static final DateTimeFormatter EXPORTED_AT =
		DateTimeFormatter.ofPattern("uuuu-MM-dd HH:mm:ss z").withZone(ZoneId.systemDefault());

	private XlsxExporter()
	{
	}

	static void write(Path target, ExportData data, DetailLevel detailLevel) throws IOException
	{
		List<Sheet> sheets = sheets(data, detailLevel);
		try (OutputStream output = Files.newOutputStream(target);
			 ZipOutputStream zip = new ZipOutputStream(output, StandardCharsets.UTF_8))
		{
			int tableCount = (int) sheets.stream().filter(Sheet::hasTable).count();
			put(zip, "[Content_Types].xml", contentTypes(sheets.size(), tableCount));
			put(zip, "_rels/.rels", ROOT_RELS);
			put(zip, "xl/workbook.xml", workbook(sheets));
			put(zip, "xl/_rels/workbook.xml.rels", workbookRelationships(sheets.size()));
			put(zip, "xl/styles.xml", STYLES);
			int tableNumber = 1;
			for (int index = 0; index < sheets.size(); index++)
			{
				Sheet sheet = sheets.get(index);
				int currentTable = sheet.hasTable() ? tableNumber++ : 0;
				writeSheet(zip, index + 1, sheet, currentTable);
				if (currentTable > 0)
				{
					put(zip, "xl/tables/table" + currentTable + ".xml",
						tableXml(currentTable, sheet));
					put(zip, "xl/worksheets/_rels/sheet" + (index + 1) + ".xml.rels",
						sheetTableRelationship(currentTable));
				}
				else if (sheet.hasLogo())
				{
					put(zip, "xl/worksheets/_rels/sheet" + (index + 1) + ".xml.rels",
						sheetDrawingRelationship());
				}
			}
			put(zip, "xl/drawings/drawing1.xml", logoDrawing());
			put(zip, "xl/drawings/_rels/drawing1.xml.rels", logoDrawingRelationship());
			put(zip, "xl/media/image1.png", BrandingAssets.logoBytes());
		}
	}

