package com.collectionlogexporter;

import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;
import net.runelite.client.hiscore.Skill;

final class HiscorePageCounters
{
	private HiscorePageCounters()
	{
	}

	static Map<String, String> map(HiscoreResult result, List<PageDefinition> definitions)
	{
		Map<String, String> counters = new HashMap<>();
		if (result == null)
		{
			return counters;
		}

		Map<String, Integer> scores = new HashMap<>();
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			if (!isUsefulCounter(skill))
			{
				continue;
			}
			Skill value = result.getSkill(skill);
			if (value != null && value.getLevel() >= 0)
			{
				scores.put(normalize(skill.getName()), value.getLevel());
			}
		}

		for (PageDefinition definition : definitions)
		{
			String pageKey = normalize(definition.getName());
			Integer count = countForPage(pageKey, scores);
			if (count != null && count >= 0)
			{
				counters.put(pageKey, "Jagex hiscores: " + count);
			}
		}
		return counters;
	}

	private static boolean isUsefulCounter(HiscoreSkill skill)
	{
		return skill.getType() == HiscoreSkillType.BOSS
			|| skill == HiscoreSkill.CLUE_SCROLL_BEGINNER
			|| skill == HiscoreSkill.CLUE_SCROLL_EASY
			|| skill == HiscoreSkill.CLUE_SCROLL_MEDIUM
			|| skill == HiscoreSkill.CLUE_SCROLL_HARD
			|| skill == HiscoreSkill.CLUE_SCROLL_ELITE
			|| skill == HiscoreSkill.CLUE_SCROLL_MASTER
			|| skill == HiscoreSkill.RIFTS_CLOSED;
	}

	private static Integer countForPage(String page, Map<String, Integer> scores)
	{
		switch (page)
		{
			case "callisto and artio":
			case "artio and callisto":
				return sum(scores, "Callisto", "Artio");
			case "venenatis and spindel":
			case "spindel and venenatis":
				return sum(scores, "Venenatis", "Spindel");
			case "vet'ion and calvar'ion":
			case "calvar'ion and vet'ion":
				return sum(scores, "Vet'ion", "Calvar'ion");
			case "dagannoth kings":
				return sum(scores, "Dagannoth Prime", "Dagannoth Rex", "Dagannoth Supreme");
			case "the nightmare":
			case "nightmare":
				return sum(scores, "Nightmare", "Phosani's Nightmare");
			case "chambers of xeric":
				return sum(scores, "Chambers of Xeric", "Chambers of Xeric: Challenge Mode");
			case "theatre of blood":
				return sum(scores, "Theatre of Blood", "Theatre of Blood: Hard Mode");
			case "tombs of amascut":
				return sum(scores, "Tombs of Amascut", "Tombs of Amascut: Expert Mode");
			case "the gauntlet":
				return sum(scores, "The Gauntlet", "The Corrupted Gauntlet");
			case "the fight caves":
			case "fight caves":
				return scores.get(normalize("TzTok-Jad"));
			case "the inferno":
			case "inferno":
				return scores.get(normalize("TzKal-Zuk"));
			case "fortis colosseum":
				return scores.get(normalize("Sol Heredit"));
			case "guardians of the rift":
				return scores.get(normalize("Rifts closed"));
			case "barrows":
				return scores.get(normalize("Barrows Chests"));
			case "the mimic":
				return scores.get(normalize("Mimic"));
			case "royal titans":
				return scores.get(normalize("The Royal Titans"));
			case "hueycoatl":
				return scores.get(normalize("The Hueycoatl"));
			case "beginner treasure trails":
				return scores.get(normalize("Clue Scrolls (beginner)"));
			case "easy treasure trails":
				return scores.get(normalize("Clue Scrolls (easy)"));
			case "medium treasure trails":
				return scores.get(normalize("Clue Scrolls (medium)"));
			case "hard treasure trails":
				return scores.get(normalize("Clue Scrolls (hard)"));
			case "elite treasure trails":
				return scores.get(normalize("Clue Scrolls (elite)"));
			case "master treasure trails":
				return scores.get(normalize("Clue Scrolls (master)"));
			default:
				return scores.get(page);
		}
	}

	private static Integer sum(Map<String, Integer> scores, String... names)
	{
		int total = 0;
		for (String name : names)
		{
			Integer value = scores.get(normalize(name));
			if (value == null)
			{
				// An unranked component is unknown, not zero. Leave the combined
				// page for a manual in-game counter instead of under-counting it.
				return null;
			}
			total += value;
		}
		return total;
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ENGLISH);
	}
}

package com.collectionlogexporter;

import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.List;

final class CsvExporter
{
	private CsvExporter()
	{
	}

	static void write(Path target, ExportData data, DetailLevel detailLevel) throws IOException
	{
		try (BufferedWriter writer = Files.newBufferedWriter(target, StandardCharsets.UTF_8))
		{
			// UTF-8 BOM keeps non-ASCII item/page names correct in older Excel versions.
			writer.write('\ufeff');
			if (detailLevel == DetailLevel.SUMMARY)
			{
				writeSummary(writer, data);
			}
			else
			{
				// CSV has one table, so BOTH uses the detailed table with page fields repeated.
				writeItems(writer, data);
			}
		}
	}

	private static void writeSummary(BufferedWriter writer, ExportData data) throws IOException
	{
		writeRow(writer, Arrays.asList(
			"Page priority",
			"Category",
			"Page",
			"Progress",
			"Obtained",
			"Total",
			"Remaining",
			"Estimated page hours",
			"KC completed",
			"Items at/over target",
			"Max KC over target",
			"Current KC / attempts"));
		for (PageSummary page : data.getPages())
		{
			writeRow(writer, Arrays.asList(
				Integer.toString(page.getRank()),
				page.getCategory(),
				page.getPage(),
				page.getObtained() + "/" + page.getTotal(),
				Integer.toString(page.getObtained()),
				Integer.toString(page.getTotal()),
				Integer.toString(page.getRemaining()),
				pageTime(page.isAnytime(), page.getEstimatedHours()),
				integer(page.getCompletedAttempts()),
				Integer.toString(page.getItemsAtOrOverRate()),
				wholeNumber(page.getMaxKcOverRate()),
				page.getCurrentAttempts()));
		}
		writeRow(writer, Arrays.asList(
			"",
			"TOTALS",
			"Official Collection Log",
			progress(data.getOfficialObtained(), data.getOfficialTotal()),
			integer(data.getOfficialObtained()),
			integer(data.getOfficialTotal()),
			data.getOfficialObtained() >= 0 && data.getOfficialTotal() >= 0
				? Integer.toString(data.getOfficialTotal() - data.getOfficialObtained())
				: "",
			"",
			"",
			"",
			"",
			"Scanned " + progress(data.getScannedObtained(), data.getScannedTotal())));
	}

	private static void writeItems(BufferedWriter writer, ExportData data) throws IOException
	{
		writeRow(writer, Arrays.asList(
			"Category",
			"Page",
			"Page progress",
			"Page remaining",
			"Missing item",
			"Estimated item hours",
			"Estimated page hours",
			"Current KC / attempts",
			"Suggested activity",
			"Page priority",
			"Attempts per hour",
			"Nominal target attempts",
			"KC completed",
			"Attempts remaining to target",
			"KC over target",
			"Estimate method",
			"Item ID"));
		for (ExportRow row : data.getRows())
		{
			writeRow(writer, Arrays.asList(
				row.getCategory(),
				row.getPage(),
				row.getObtained() + "/" + row.getTotal(),
				Integer.toString(row.getRemaining()),
				row.getItemName(),
				itemTime(row.isItemAnytime(), row.getEstimatedItemHours()),
				pageTime(row.isPageAnytime(), row.getEstimatedPageHours()),
				row.getCurrentAttempts(),
				row.getActivity(),
				Integer.toString(row.getClosestRank()),
				wholeNumber(row.getAttemptsPerHour()),
				wholeNumber(row.getExpectedAdditionalAttempts()),
				integer(row.getCompletedAttempts()),
				wholeNumber(row.getAttemptsToRate()),
				wholeNumber(row.getKcOverRate()),
				row.getEstimateMethod(),
				Integer.toString(row.getItemId())));
		}
		writeRow(writer, Arrays.asList(
			"TOTALS",
			"Official Collection Log",
			progress(data.getOfficialObtained(), data.getOfficialTotal()),
			data.getOfficialObtained() >= 0 && data.getOfficialTotal() >= 0
				? Integer.toString(data.getOfficialTotal() - data.getOfficialObtained())
				: "",
			"Missing item rows",
			"",
			"",
			"Scanned " + progress(data.getScannedObtained(), data.getScannedTotal()),
			"",
			"",
			"",
			"",
			"",
			"",
			"",
			"",
			""));
	}

	private static String wholeNumber(double value)
	{
		return Double.isFinite(value) ? Long.toString(Math.round(value)) : "";
	}

	private static String integer(int value)
	{
		return value >= 0 ? Integer.toString(value) : "";
	}

	private static String itemTime(boolean anytime, double hours)
	{
		return anytime || !Double.isFinite(hours)
			? anytime ? "Anytime" : "Estimate unavailable"
			: Math.abs(hours) < 10.0
				? trimDecimal(hours)
				: Long.toString(Math.round(hours));
	}

	private static String pageTime(boolean anytime, double hours)
	{
		return anytime || !Double.isFinite(hours)
			? anytime ? "Anytime" : "Estimate unavailable"
			: String.format(java.util.Locale.ENGLISH, "%.2f", hours);
	}

	private static String trimDecimal(double value)
	{
		return String.format(java.util.Locale.ENGLISH, "%.3f", value)
			.replaceAll("0+$", "")
			.replaceAll("\\.$", "");
	}

	private static String progress(int obtained, int total)
	{
		return obtained >= 0 && total >= 0 ? obtained + "/" + total : "";
	}

	private static void writeRow(BufferedWriter writer, List<String> values) throws IOException
	{
		for (int index = 0; index < values.size(); index++)
		{
			if (index > 0)
			{
				writer.write(',');
			}
			writer.write(quote(values.get(index)));
		}
		writer.newLine();
	}

	static String quote(String value)
	{
		String safe = value == null ? "" : value;
		return "\"" + safe.replace("\"", "\"\"") + "\"";
	}
}

